import {esc,request} from './customer-shared.mjs';
const root=document.querySelector('#course-app');
let current;
function shell(s){const ready=s.verified&&!s.paymentHold;const mode=s.mode==='sandbox'||s.sample===false?'PAYPAL SANDBOX':s.mode==='sample'?'FICTIONAL SAMPLE':'PURCHASE DEMO';root.removeAttribute('role');root.innerHTML=`<section class="hero" id="overview"><div class="frame hero-inner"><div><span class="eyebrow">YOUR LEARNER SPACE · ${mode}</span><h1>See the light.<br><em>Tell the story.</em></h1><p>A workshop in noticing, composing, and making images that feel like yours. Your first lesson opens here when your purchase and access are verified.</p></div><div class="hero-art" aria-hidden="true"><div class="art-window"></div><div class="art-caption">A little light changes everything.</div></div></div></section><div class="frame content"><section id="lesson" aria-labelledby="lesson-heading"><div class="lead"><h2 id="lesson-heading">Your first lesson</h2><span class="pill ${ready?'':'locked'}">${ready?'Access ready':'Access locked'}</span></div><article class="lesson-card"><div class="lesson-scene"><span>01 / The light you already have</span></div><div class="lesson-body"><span class="eyebrow lesson-index">THE LIGHT & STORY WORKSHOP</span><h3>Find your light.</h3><p>Start with a simple scene, one ordinary object, and a fresh way of seeing it.</p><div class="state ${ready?'ready':''}" role="status"><strong>${ready?'Your lesson is ready':'Your lesson is still locked'}</strong><small>${ready?'Open it here. We will check the protected lesson again before displaying its content.':'Your purchase may be complete, but access has not yet been verified. You do not need to pay again.'}</small></div>${ready?'<button class="action" id="open-lesson" type="button">Open the lesson →</button>':'<a class="action secondary" href="customer.html">View purchase progress →</a>'}<div id="lesson-result" aria-live="polite"></div></div></article></section><aside aria-label="Your workshop progress"><section class="side-card"><span class="eyebrow">YOUR PATH</span><h2>One step at a time.</h2><ol><li class="active">Find your light · first lesson</li><li>Shape the frame</li><li>Make the story yours</li></ol></section><section class="side-card"><span class="eyebrow">PURCHASE STATUS</span><h2>${ready?'Ready to begin':'We’re checking access'}</h2><p>${esc(s.next)}. The merchant can help from your private case.</p><p class="meta">Case ${esc(s.caseId)} · ${esc(s.amount)}</p><a href="customer.html">Open your private case →</a></section></aside></div>`;
root.querySelector('#open-lesson')?.addEventListener('click',openLesson);
}
async function openLesson(){const button=root.querySelector('#open-lesson'),target=root.querySelector('#lesson-result');button.disabled=true;button.textContent='Opening your lesson…';try{const lesson=await request('/api/customer/lesson?caseId='+encodeURIComponent(current.caseId));target.innerHTML=`<div class="lesson-content"><h4>${esc(lesson.title)}</h4><p>${esc(lesson.body)}</p><p class="meta">Protected lesson content opened for this private learner session.</p></div>`;button.textContent='Lesson open';if(lesson.browserChallenge&&crypto.subtle){try{const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(lesson.body)))).map(x=>x.toString(16).padStart(2,'0')).join('');await request('/api/customer/browser-proof',{caseId:current.caseId,token:lesson.browserChallenge,digest});}catch{target.insertAdjacentHTML('beforeend','<p class="meta">The lesson opened, but the separate browser receipt was not recorded.</p>');}}}catch(error){target.innerHTML=`<p class="error" role="alert">${esc(error.message)} <a href="customer.html">Check your private case</a> or try again.</p>`;button.disabled=false;button.textContent='Try opening the lesson';}}
async function init(){try{current=await request('/api/customer/case');shell(current);}catch{root.innerHTML='<div class="frame loading"><h1>Your lesson is private.</h1><p>Open the private case link your merchant shared, then return to this workshop page.</p><a class="action" href="customer.html">Find your purchase →</a></div>';}}
await init();
